cards.details:
Exemple de la page :

interface Pet {
  name: string;
}

class Dog {
  name = "Rex";
}

let pet: Pet = new Dog(); // OK : Dog n'implemente pas Pet mais a la bonne forme

const dog = { name: "Lassie", owner: "Rudd Weatherwax" };
pet = dog; // OK : owner est ignore

const pet2: Pet = { name: "Lassie", owner: "Rudd Weatherwax" };
// Error: Object literal may only specify known properties,
// and 'owner' does not exist in type 'Pet'.

let myName = "Alice"; // infere string, pas besoin d'annotation

const names = ["Alice", "Bob", "Eve"];
// contextual typing : s est infere string
names.forEach((s) => {
  console.log(s.toUpperCase());
});

// Hors contexte, rien a inferer : any implicite
const handler = function (e) { return e; };
// Error (noImplicitAny): Parameter 'e' implicitly has an 'any' type.

function f1(a: any) {
  a.b(); // OK, aucune verification
}
function f2(a: unknown) {
  a.b(); // Error: 'a' is of type 'unknown'.
  if (typeof a === "string") a.toUpperCase(); // OK apres narrowing
}

function fail(msg: string): never {
  throw new Error(msg);
}

function fn(x: string | number) {
  if (typeof x === "string") {
  } else if (typeof x === "number") {
  } else {
    x; // never
  }
}

interface Window2 { title: string; }
interface Window2 { ts: number; } // fusionne : Window2 a title et ts

type Win = { title: string };
type Win = { ts: number };
// Error: Duplicate identifier 'Win'.

interface IBear extends IAnimal { honey: boolean }
type Bear = Animal & { honey: boolean };

type Id = string | number; // impossible avec une interface

