Le meme widening existe sur let :

let changing = "Hello";  // string
const constant = "Hello"; // "Hello" (literal type)

const req2 = { url: "https://example.com", method: "GET" } as const;
// { readonly url: "https://example.com"; readonly method: "GET" }
handleRequest(req2.url, req2.method); // OK
req2.method = "POST";
// Error: Cannot assign to 'method' because it is a read-only property.

const canvas = document.getElementById("main") as HTMLCanvasElement;

const x = "hello" as number;
// Error: Conversion of type 'string' to type 'number' may be a mistake because
// neither type sufficiently overlaps with the other. If this was intentional,
// convert the expression to 'unknown' first.

const y = "hello" as unknown as number; // compile, mais faux au runtime

function liveDangerously(v?: number | null) {
  console.log(v!.toFixed()); // pas d'erreur de compilation
}

