cards.details:
readonly n'est pas pris en compte dans la compatibilite des types : un objet Person modifiable peut etre assigne a un ReadonlyPerson, et le modifier via l'alias original change ce qu'on lit via l'alias readonly.

Propriete optionnelle vs | undefined :

interface A { a?: string }
interface B { a: string | undefined }
const a1: A = {}; // OK
const b1: B = {};
// Error: Property 'a' is missing in type '{}' but required in type 'B'.

// Avec exactOptionalPropertyTypes, a?: string refuse aussi { a: undefined }.

const users = [{ name: "Oby", age: 12 }, { name: "Heera", age: 32 }];
const loggedInUser = users.find((u) => u.name === loggedInUsername);

console.log(loggedInUser.age);
// strictNullChecks on : 'loggedInUser' is possibly 'undefined'.
// strictNullChecks off : aucune erreur, crash possible au runtime

console.log(loggedInUser?.age); // OK

Union (Everyday Types) :

function printId(id: number | string) {
  console.log(id.toUpperCase());
  // Property 'toUpperCase' does not exist on type 'string | number'.
  //   Property 'toUpperCase' does not exist on type 'number'.
}

// Une methode commune a tous les membres reste utilisable :
function getFirstThree(x: number[] | string) {
  return x.slice(0, 3); // retour : number[] | string
}

Intersection (Handbook, Object Types, https://www.typescriptlang.org/docs/handbook/2/objects.html#intersection-types) :

interface Colorful { color: string; }
interface Circle { radius: number; }
type ColorfulCircle = Colorful & Circle; // color ET radius

Si une même propriété a des types incompatibles, l'intersection compile mais la propriété devient never :

interface Person1 { name: string; }
interface Person2 { name: number; }
type Staff = Person1 & Person2; // Staff["name"] : never

type Fish = { swim: () => void };
type Bird = { fly: () => void };
type Human = { swim?: () => void; fly?: () => void };

function move(animal: Fish | Bird | Human) {
  if ("swim" in animal) {
    animal; // Fish | Human
  } else {
    animal; // Bird | Human
  }
}

interface Container {
  value: number | null | undefined;
}
function multiplyValue(container: Container, factor: number) {
  if (container.value != null) {
    container.value *= factor; // number : null ET undefined retires
  }
}

function logValue(x: Date | string) {
  if (x instanceof Date) {
    console.log(x.toUTCString()); // Date
  } else {
    console.log(x.toUpperCase()); // string
  }
}

