cards.details:
Correction recommandée par la doc (vérification d'égalité, qui ne touche pas la chaîne vide) :

function printAll(strs: string | string[] | null) {
  if (strs !== null) {
    if (typeof strs === "object") {
      for (const s of strs) {
        console.log(s); // strs : string[]
      }
    } else if (typeof strs === "string") {
      console.log(strs); // strs : string
    }
  }
}

interface Circle {
  kind: "circle";
  radius: number;
}
interface Square {
  kind: "square";
  sideLength: number;
}
type Shape = Circle | Square;

function getArea(shape: Shape) {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2; // shape : Circle
    case "square":
      return shape.sideLength ** 2; // shape : Square
  }
}

Cas d'usage cités par la doc : messages échangés sur le réseau (client/serveur), mutations dans un framework de state management.

cards.code:
interface Circle { kind: "circle"; radius: number; }
interface Square { kind: "square"; sideLength: number; }
interface Triangle { kind: "triangle"; sideLength: number; }

type Shape = Circle | Square | Triangle;

function getArea(shape: Shape) {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.sideLength ** 2;
    default:
      const _exhaustiveCheck: never = shape;
      return _exhaustiveCheck;
  }
}

