Predicate explicite (Handbook, https://www.typescriptlang.org/docs/handbook/2/narrowing.html#using-type-predicates) :

function isFish(pet: Fish | Bird): pet is Fish {
  return (pet as Fish).swim !== undefined;
}
const underWater: Fish[] = zoo.filter(isFish);

Predicates inférés depuis 5.5 :

// const isNumber: (x: unknown) => x is number
const isNumber = (x: unknown) => typeof x === "number";

// Avant : (number | null)[] ; maintenant : number[]
const nums = [1, 2, 3, null, 5].filter(x => x !== null);
nums.push(null); // ok en 5.4, erreur en 5.5

Sémantique « si et seulement si » : true → x est T, false → x n'est pas T.

function assert(condition: any, msg?: string): asserts condition {
  if (!condition) {
    throw new Error(msg);
  }
}

function assertIsString(val: any): asserts val is string {
  if (typeof val !== "string") {
    throw new Error("Not a string!");
  }
}

function yell(str: any) {
  assertIsString(str);
  // Pas de if : str est string pour la suite
  return str.toUppercase();
  // Property 'toUppercase' does not exist on type 'string'.
  // Did you mean 'toUpperCase'?
}

// Version generique :
function assertIsDefined<T>(val: T): asserts val is NonNullable<T> {
  if (val === undefined || val === null) {
    throw new Error(`Expected 'val' to be defined, but received ${val}`);
  }
}

Assignations (Handbook) :

let x = Math.random() < 0.5 ? 10 : "hello world!"; // string | number
x = 1;          // x : number
x = "goodbye!"; // ok, x : string
x = true;       // Type 'boolean' is not assignable to type 'string | number'.

Closures (TS 5.4, https://www.typescriptlang.org/docs/handbook/release-notes/typescript-5-4.html#preserved-narrowing-in-closures-following-last-assignments) :

function getUrls(url: string | URL, names: string[]) {
  if (typeof url === "string") {
    url = new URL(url);
  }
  return names.map(name => {
    url.searchParams.set("name", name); // ok depuis 5.4 : url est URL
    return url.toString();
  });
}

function printValueLater(value: string | undefined) {
  if (value === undefined) {
    value = "missing!";
  }
  setTimeout(() => {
    value = value; // assignation dans une fonction imbriquee
  }, 500);
  setTimeout(() => {
    console.log(value.toUpperCase());
    // 'value' is possibly 'undefined'.
  }, 1000);
}

type GreetFunction = (a: string) => void;

type DescribableFunction = {
  description: string;
  (someArg: number): boolean;
};

type SomeConstructor = {
  new (s: string): Date;
};

// Piege : le nom du parametre est obligatoire
type Bad = (string) => void; // parametre nomme string, de type any
// (en strict, noImplicitAny le signale : Parameter has a name but no type.)

function len(s: string): number;
function len(arr: any[]): number;
function len(x: any) {
  return x.length;
}

len(Math.random() > 0.5 ? "hello" : [0]);
// Error: No overload matches this call.

// Mieux :
