interface Box<T = string> {
  value: T;
}
const b1: Box = { value: "ok" };       // T = string
const b2: Box<number> = { value: 42 }; // T = number

declare function make<T = string>(): T[];
const m = make(); // string[] : aucun candidat d'inference, le defaut s'applique

type Pair<A = string, B> = [A, B];
// Required type parameters may not follow optional type parameters.

type Id<T extends string = number> = T;
// Type 'number' does not satisfy the constraint 'string'.

Une déclaration de class ou d'interface qui fusionne avec une existante peut ajouter un défaut à un type parameter existant, ou un nouveau type parameter à condition qu'il ait un défaut.

type HasNames = { names: readonly string[] };

function getNamesExactly<const T extends HasNames>(arg: T): T["names"] {
  return arg.names;
}

// readonly ["Alice", "Bob", "Eve"], sans as const
const names = getNamesExactly({ names: ["Alice", "Bob", "Eve"] });

Sans le modificateur const, le même appel infère string[], et il faut écrire { names: [...] } as const pour obtenir le tuple readonly.

